import pandas as pd

def binary_tree_nodes(tree: pd.DataFrame) -> pd.DataFrame:
    parents = set(tree['P'].dropna().unique())
    def classify(row):
        if pd.isna(row['P']):
            return 'Root'
        elif row['N'] not in parents:
            return 'Leaf'
        else:
            return 'Inner'

    res = tree[['N']].copy().drop_duplicates()
    res['Type'] = tree.apply(classify, axis=1)
    return res.sort_values(by='N')
